import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import * as Haptics from 'expo-haptics';
import { useEffect, useSyncExternalStore } from 'react';
import { AppState, Platform } from 'react-native';

import { settings, useSettings } from '../settings';

// Sound effects, music and haptics, each switchable in Settings. The sounds
// are generated by scripts/make-sounds.mjs.

const EFFECTS = {
  place: { source: require('../../assets/sounds/place.wav'), volume: 0.45 },
  tap: { source: require('../../assets/sounds/tap.wav'), volume: 0.3 },
  swap: { source: require('../../assets/sounds/swap.wav'), volume: 0.5 },
  ok: { source: require('../../assets/sounds/ok.wav'), volume: 0.55 },
  great: { source: require('../../assets/sounds/great.wav'), volume: 0.65 },
  poetic: { source: require('../../assets/sounds/poetic.wav'), volume: 0.75 },
  invalid: { source: require('../../assets/sounds/invalid.wav'), volume: 0.55 },
  star1: { source: require('../../assets/sounds/star1.wav'), volume: 0.6 },
  star2: { source: require('../../assets/sounds/star2.wav'), volume: 0.6 },
  star3: { source: require('../../assets/sounds/star3.wav'), volume: 0.65 },
  win: { source: require('../../assets/sounds/win.wav'), volume: 0.7 },
  lose: { source: require('../../assets/sounds/lose.wav'), volume: 0.6 },
  hoot: { source: require('../../assets/sounds/hoot.wav'), volume: 0.7 },
};

export type SoundName = keyof typeof EFFECTS;

const MUSIC_VOLUME = 0.28;

let audioReady = false;
function prepareAudio() {
  if (audioReady) return;
  audioReady = true;
  // Respect the silent switch and let the player's own music keep playing.
  setAudioModeAsync({
    playsInSilentMode: false,
    interruptionMode: 'mixWithOthers',
    shouldPlayInBackground: false,
  }).catch(() => {});
}

const players = new Map<SoundName, AudioPlayer>();

export function playSound(name: SoundName) {
  if (!settings.snapshot().sound) return;
  try {
    prepareAudio();
    let player = players.get(name);
    if (!player) {
      player = createAudioPlayer(EFFECTS[name].source);
      player.volume = EFFECTS[name].volume;
      players.set(name, player);
    }
    player.seekTo(0).catch(() => {});
    player.play();
  } catch (e) {
    console.warn(`Couldn't play ${name}:`, e);
  }
}

export type HapticKind = 'select' | 'tap' | 'success' | 'warning' | 'error';

export function haptic(kind: HapticKind) {
  if (Platform.OS === 'web' || !settings.snapshot().haptics) return;
  const run =
    kind === 'select'
      ? Haptics.selectionAsync()
      : kind === 'tap'
        ? Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light)
        : Haptics.notificationAsync(
            kind === 'success'
              ? Haptics.NotificationFeedbackType.Success
              : kind === 'warning'
                ? Haptics.NotificationFeedbackType.Warning
                : Haptics.NotificationFeedbackType.Error,
          );
  run.catch(() => {});
}

let music: AudioPlayer | null = null;
function setMusic(on: boolean) {
  try {
    if (!music) {
      if (!on) return;
      prepareAudio();
      music = createAudioPlayer(require('../../assets/sounds/music.wav'));
      music.loop = true;
      music.volume = MUSIC_VOLUME;
    }
    if (on) music.play();
    else music.pause();
  } catch (e) {
    console.warn("Couldn't play music:", e);
  }
}

const subscribeAppState = (listener: () => void) => {
  const subscription = AppState.addEventListener('change', listener);
  return () => subscription.remove();
};

/** Plays the music loop while it's switched on and the app is in front. Use once, at the root. */
export function useMusic() {
  const { music: enabled } = useSettings();
  const appState = useSyncExternalStore(subscribeAppState, () => AppState.currentState);
  const playing = enabled && appState === 'active';

  useEffect(() => {
    if (Platform.OS !== 'web' || !playing) {
      setMusic(playing);
      return;
    }
    // Browsers only allow sound after the first tap or key press.
    const start = () => setMusic(true);
    window.addEventListener('pointerdown', start, { once: true });
    return () => window.removeEventListener('pointerdown', start);
  }, [playing]);
}
